// Broker-owned, ephemeral loopback listener with real before/after controls.
using System;using System.Net;using System.Net.Sockets;using System.Threading;using System.Text;
internal sealed class LpacLoopbackFixture {
    readonly TcpListener listener;readonly Thread worker;readonly Action<string,object> record;int accepted;volatile bool stopping;string failure;
    internal readonly int Port;
    internal LpacLoopbackFixture(Action<string,object> record){this.record=record;listener=new TcpListener(IPAddress.Loopback,0);listener.Start();Port=((IPEndPoint)listener.LocalEndpoint).Port;
        worker=new Thread(delegate(){try{while(!stopping){using(var client=listener.AcceptTcpClient()){Interlocked.Increment(ref accepted);}}}catch(SocketException e){if(!stopping)failure=e.ToString();}catch(Exception e){failure=e.ToString();}});worker.IsBackground=true;worker.Start();try{Control("before");record("loopback_fixture_started",new{address="127.0.0.1",port=Port,host_positive_control=true,external_network=false});}catch{stopping=true;listener.Stop();worker.Join(3000);throw;}}
    void Control(string stage){int before=Interlocked.CompareExchange(ref accepted,0,0);using(var client=new TcpClient()){client.Connect(IPAddress.Loopback,Port);}var timer=System.Diagnostics.Stopwatch.StartNew();while(Interlocked.CompareExchange(ref accepted,0,0)<=before&&timer.ElapsedMilliseconds<2000)Thread.Sleep(10);if(Interlocked.CompareExchange(ref accepted,0,0)!=before+1||failure!=null)throw new InvalidOperationException("LOOPBACK_CONTROL_UNKNOWN");record("loopback_host_control",new{stage=stage,port=Port,actual_connected=true,accepted=Interlocked.CompareExchange(ref accepted,0,0)});}
    internal bool Finish(){bool ok=false;try{Control("after");ok=Interlocked.CompareExchange(ref accepted,0,0)==2&&failure==null;}finally{stopping=true;listener.Stop();if(!worker.Join(3000))throw new InvalidOperationException("LOOPBACK_WORKER_REMAINS");}record("loopback_fixture_after",new{accepted=Interlocked.CompareExchange(ref accepted,0,0),expected_host_controls=2,application_connections=Interlocked.CompareExchange(ref accepted,0,0)-2,stopped=true,worker_failure=failure,accepted_boundary=ok});return ok;}
}
